🐛 Bug
complie with libtorch prebuilt lib failed
To Reproduce
Steps to reproduce the behavior:

download libtorch form https://download.pytorch.org/libtorch/cpu/libtorch-cxx11-abi-shared-with-deps-1.8.1%2Bcpu.zip
cmake .. -DCMAKE_PREFIX_PATH=/data/practice/pytorch/test/libtorch
make

Sample code:
#include "torch/script.h"
#include "torch/torch.h"

#include <iostream>
#include <memory>

using namespace std;

int main(int argc, const char* argv[])
{
    if (argc != 2) {
        std::cerr << "usage: example-app <path-to-exported-script-module>\n";
        return -1;
    }

    torch::jit::script::Module module;
    try {
        module = torch::jit::load(argv[1]);
    }
    catch (const c10::Error& e) {
        std::cerr << "error loading the model\n";
        return -1;
    }


    std::cout << "ok\n";

    std::vector<torch::jit::IValue> inputs;
    inputs.push_back(torch::ones({1, 3, 32, 32}));

    at::Tensor output = module.forward(inputs).toTensor();

    std::cout << output.slice(/*dim=*/1, /*start=*/0, /*end=*/5) << '\n';
}

CMakeLists.txt
cmake_minimum_required(VERSION 3.0.0 FATAL_ERROR)
project(example)
find_package(Torch REQUIRED)

message(STATUS "Pytorch status:")
message(STATUS "    libraries: ${TORCH_LIBRARIES}")
add_executable(example test.cc)
target_link_libraries(example ${TORCH_LIBRARIES})
set_property(TARGET example PROPERTY CXX_STANDARD 11)

Expected behavior
compile without error
Environment
compile.log
Ubuntu 16.04.7 LTS
gcc 5.4
pytorch 1.8.1(download libtorch from pytorch website)
